import{_ as t,o,c as a,a2 as d}from"./chunks/framework.CBxkvBm_.js";const m=JSON.parse('{"title":"CSV Tabular Data (.csv)","description":"","frontmatter":{},"headers":[],"relativePath":"languages/csv.md","filePath":"languages/csv.md"}'),c={name:"languages/csv.md"};function l(i,e,n,s,r,u){return o(),a("div",null,[...e[0]||(e[0]=[d('<h1 id="csv-tabular-data-csv" tabindex="-1">CSV Tabular Data (<code>.csv</code>) <a class="header-anchor" href="#csv-tabular-data-csv" aria-label="Permalink to &quot;CSV Tabular Data (`.csv`)&quot;">​</a></h1><p><code>@modelscript/csv</code> (<code>languages/csv</code>) elevates empirical measurement series, calibration look-up tables, and parameter sweeps into first-class typed symbols inside the <code>WorkspaceIndex</code>.</p><hr><h2 id="capabilities" tabindex="-1">Capabilities <a class="header-anchor" href="#capabilities" aria-label="Permalink to &quot;Capabilities&quot;">​</a></h2><ol><li><strong>Native GLR Parsing &amp; Delimiter Auto-Detection</strong>: Parses RFC 4180 CSV documents into linear-memory CST rows and cells (<code>csv_document</code>, <code>header_row</code>, <code>data_row</code>, <code>field</code>, <code>quoted_field</code>) while <code>detectDelimiter</code> (<code>languages/csv/src/measurements.ts</code>) automatically detects comma (<code>,</code>), semicolon (<code>;</code>), or tab (<code>\\t</code>) delimiters and handles quoted strings with escaped <code>&quot;&quot;</code> sequences.</li><li><strong>Modelica Package Generation (<code>parseCsvToModelica</code>)</strong>: Converts any CSV dataset directly into a strongly typed Modelica <code>package</code> containing: <ul><li><code>constant Integer numRows</code> and <code>constant Integer numCols</code></li><li>A 2D <code>constant Real values[numRows, numCols]</code> matrix suitable for <code>Modelica.Blocks.Tables.CombiTable1D</code> / <code>CombiTable2D</code></li><li>Sanitized 1D column vectors (<code>constant Real &lt;colName&gt;[numRows]</code>) with automatic duplicate-name disambiguation</li></ul></li><li><strong>Salsa Virtual Component Queries (<code>CSVVirtualComponent</code>)</strong>: Exposes every CSV column as a queryable virtual symbol in the <code>QueryEngine</code> (<code>languages/csv/src/queries.ts</code>): <ul><li><code>resolvedType</code>: Infers <code>&quot;Real&quot;</code>, <code>&quot;Integer&quot;</code>, <code>&quot;Boolean&quot;</code>, or <code>&quot;String&quot;</code> from column cells</li><li><code>classInstance</code>: Maps to <code>&quot;Modelica.Blocks.Sources.CombiTimeTable&quot;</code></li><li><code>variability</code>: Returns <code>&quot;constant&quot;</code></li><li><code>causality</code>: Returns <code>&quot;output&quot;</code></li><li><code>resolvedArrayDimensions</code> / <code>arrayDimensions</code>: Returns <code>[rowCount]</code></li><li><code>effectiveModification</code>: Synthesizes <code>{ table: &quot;[[...]]&quot; }</code> array literals from column data</li></ul></li><li><strong>Bidirectional Cell Writeback (<code>writeback</code>)</strong>: When a parameter or table entry is modified during calibration or optimization, <code>csvLanguage.writeback</code> (<code>languages/csv/src/language.ts</code>) updates the exact <code>[row, col]</code> cell or column header in place while preserving the file&#39;s original delimiter and line endings.</li></ol><hr><h2 id="semantic-linter-diagnostic-codes" tabindex="-1">Semantic Linter &amp; Diagnostic Codes <a class="header-anchor" href="#semantic-linter-diagnostic-codes" aria-label="Permalink to &quot;Semantic Linter &amp; Diagnostic Codes&quot;">​</a></h2><p><code>lintCsv(sourceText)</code> (<code>languages/csv/src/linter.ts</code>) performs six structural and numerical integrity checks on CSV datasets:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Code</th><th style="text-align:left;">Severity</th><th style="text-align:left;">Condition Checked</th></tr></thead><tbody><tr><td style="text-align:left;"><code>CSV_UNCLOSED_QUOTE</code></td><td style="text-align:left;"><code>error</code></td><td style="text-align:left;">A quoted field contains an unclosed <code>&quot;</code> at the end of a line</td></tr><tr><td style="text-align:left;"><code>CSV_EMPTY_HEADER</code></td><td style="text-align:left;"><code>warning</code></td><td style="text-align:left;">A column in the header row has an empty name</td></tr><tr><td style="text-align:left;"><code>CSV_DUPLICATE_HEADER</code></td><td style="text-align:left;"><code>warning</code></td><td style="text-align:left;">Two or more columns share the same header identifier</td></tr><tr><td style="text-align:left;"><code>CSV_COLUMN_COUNT_MISMATCH</code></td><td style="text-align:left;"><code>error</code></td><td style="text-align:left;">A data row contains fewer or more cells than the header row</td></tr><tr><td style="text-align:left;"><code>CSV_INVALID_NUMERIC_CELL</code></td><td style="text-align:left;"><code>error</code></td><td style="text-align:left;">A cell in a numeric column (where row 1 is numeric) contains non-numeric text, <code>NaN</code>, or <code>Infinity</code></td></tr><tr><td style="text-align:left;"><code>CSV_NON_MONOTONIC_TIME</code></td><td style="text-align:left;"><code>warning</code></td><td style="text-align:left;">The first column (<code>time</code> / <code>t</code>) is not strictly monotonically increasing ($t_i &lt; t_{i-1}$)</td></tr></tbody></table><hr><h2 id="polyglot-tgg-rules" tabindex="-1">Polyglot TGG Rules <a class="header-anchor" href="#polyglot-tgg-rules" aria-label="Permalink to &quot;Polyglot TGG Rules&quot;">​</a></h2><p><code>@modelscript/csv</code> registers 2 bidirectional Triple Graph Grammar (TGG) rules in <code>languages/csv/src/language.ts</code>:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Rule Name</th><th style="text-align:left;">Source (<code>csv</code>)</th><th style="text-align:left;">Target (<code>modelica</code>)</th><th style="text-align:left;">Semantics</th></tr></thead><tbody><tr><td style="text-align:left;"><code>CsvDocumentToModelicaPackage</code></td><td style="text-align:left;"><code>CSVDocument</code></td><td style="text-align:left;"><code>ClassDefinition</code> (<code>package</code>)</td><td style="text-align:left;">Projects a CSV file into a Modelica data package with <code>values[numRows, numCols]</code></td></tr><tr><td style="text-align:left;"><code>CsvVirtualComponentToModelicaComponent</code></td><td style="text-align:left;"><code>CSVVirtualComponent</code></td><td style="text-align:left;"><code>ComponentClause</code> (<code>parameter Real</code>)</td><td style="text-align:left;">Binds a typed CSV column to a Modelica parameter vector or <code>CombiTimeTable</code> source</td></tr></tbody></table>',13)])])}const h=t(c,[["render",l]]);export{m as __pageData,h as default};
